class Solution {
public:
    vector<vector<int>> combinationSum2(vector<int>& candidates, int target) {
        sort(candidates.begin(), candidates.end());
        vector<vector<int>> res;
        vector<int> path;
        auto dfs = [&](auto& self, int start, int remain) -> void {
            if (remain == 0) {
                res.push_back(path);
                return;
            }
            for (int i = start; i < (int)candidates.size(); ++i) {
                if (candidates[i] > remain) break;
                if (i > start && candidates[i] == candidates[i - 1]) continue;
                path.push_back(candidates[i]);
                self(self, i + 1, remain - candidates[i]);
                path.pop_back();
            }
        };
        dfs(dfs, 0, target);
        return res;
    }
};

class Solution {
    public List<List<Integer>> combinationSum2(int[] candidates, int target) {
        Arrays.sort(candidates);
        List<List<Integer>> res = new ArrayList<>();
        List<Integer> path = new ArrayList<>();
        dfs(candidates, target, 0, path, res);
        return res;
    }
    private void dfs(int[] nums, int remain, int start, List<Integer> path, List<List<Integer>> res) {
        if (remain == 0) {
            res.add(new ArrayList<>(path));
            return;
        }
        for (int i = start; i < nums.length; i++) {
            if (nums[i] > remain) break;
            if (i > start && nums[i] == nums[i - 1]) continue;
            path.add(nums[i]);
            dfs(nums, remain - nums[i], i + 1, path, res);
            path.remove(path.size() - 1);
        }
    }
}

var combinationSum2 = function(candidates, target) {
    candidates.sort((a, b) => a - b);
    const res = [];
    const path = [];
    function backtrack(start, remain) {
        if (remain === 0) {
            res.push([...path]);
            return;
        }
        for (let i = start; i < candidates.length; i++) {
            if (candidates[i] > remain) break;
            if (i > start && candidates[i] === candidates[i - 1]) continue;
            path.push(candidates[i]);
            backtrack(i + 1, remain - candidates[i]);
            path.pop();
        }
    }
    backtrack(0, target);
    return res;
};
